function validate([nums]) {
  if (nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each value is an integer between 0 and 100.';
  return null;
}

