function checkPrimeFrequency(nums) {
  // For every element, count its copies with a filter, then count that frequency's divisors.
  for (const x of nums) {
    const freq = nums.filter(v => v === x).length;
    let divisors = 0;
    for (let d = 1; d <= freq; d++) if (freq % d === 0) divisors++;
    if (divisors === 2) return true;
  }
  return false;
}

