function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const nums = [];
  if (rand() < 0.5) {
    // Build the array from non-prime frequencies only, so the answer is false.
    const target = size === 'large' ? 100 : int(1, 10);
    const plain = [1, 1, 1, 4, 6, 8, 9, 10, 12, 16, 25];
    const pool = Array.from({ length: 101 }, (_, v) => v);
    while (nums.length < target) {
      let count = plain[int(0, plain.length - 1)];
      if (count > target - nums.length) count = 1;
      const value = pool.splice(int(0, pool.length - 1), 1)[0];
      for (let i = 0; i < count; i++) nums.push(value);
    }
  } else {
    const n = size === 'large' ? 100 : int(1, 10);
    const top = rand() < 0.5 ? int(0, 5) : 100;
    for (let i = 0; i < n; i++) nums.push(int(0, top));
  }
  for (let i = nums.length - 1; i > 0; i--) {
    const j = int(0, i);
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
